<?php defined('BASEPATH') OR exit('No direct script access allowed'); class Learn_scope_progress_model extends CI_Model {public function get($m,$id){$id=(int)$id;if($m==='flashcard'){$e=$this->db->get_where('learn_flashcard_decks',['id'=>$id])->row_array();$r=$this->db->select('p.user_id,u.full_name,u.username,COUNT(*) attempts,SUM(p.status="known") score,MAX(p.last_reviewed_at) last_at',false)->from('learn_flashcard_progress p')->join('auth_user u','u.id=p.user_id','left')->where('p.deck_id',$id)->group_by(['p.user_id','u.full_name','u.username'])->get()->result_array();}elseif($m==='story'){$e=$this->db->get_where('learn_story_passages',['id'=>$id])->row_array();$r=$this->db->select('a.user_id,u.full_name,u.username,COUNT(*) attempts,MAX(a.score_percent) score,MAX(a.created_at) last_at',false)->from('learn_story_attempts a')->join('auth_user u','u.id=a.user_id','left')->where('a.passage_id',$id)->group_by(['a.user_id','u.full_name','u.username'])->get()->result_array();}elseif($m==='mini_games'){$e=$this->db->get_where('learn_game_content_sets',['id'=>$id])->row_array();$r=$this->db->select('s.user_id,u.full_name,u.username,COUNT(*) attempts,MAX(s.score) score,MAX(s.played_at) last_at',false)->from('learn_game_sessions s')->join('auth_user u','u.id=s.user_id','left')->where('s.content_set_id',$id)->group_by(['s.user_id','u.full_name','u.username'])->get()->result_array();}elseif($m==='battle'){$e=$this->db->get_where('learn_battle_sessions',['id'=>$id])->row_array();$r=$this->db->select('p.user_id,u.full_name,u.username,COUNT(*) attempts,MAX(p.score) score,MAX(p.finished_at) last_at',false)->from('learn_battle_participants p')->join('learn_battle_rooms x','x.id=p.room_id')->join('auth_user u','u.id=p.user_id','left')->where('x.battle_session_id',$id)->group_by(['p.user_id','u.full_name','u.username'])->get()->result_array();}else return null;return $e?['module'=>$m,'entity'=>$e,'players'=>$r]:null;}public function reset($m,$id,$uid){$id=(int)$id;$uid=(int)$uid;$this->db->trans_start();if($m==='flashcard')$this->db->where(['deck_id'=>$id,'user_id'=>$uid])->delete('learn_flashcard_progress');elseif($m==='story')$this->db->where(['passage_id'=>$id,'user_id'=>$uid])->delete('learn_story_attempts');elseif($m==='mini_games')$this->db->where(['content_set_id'=>$id,'user_id'=>$uid])->delete('learn_game_sessions');elseif($m==='battle'){$ids=array_column($this->db->select('id')->where(['battle_session_id'=>$id,'status'=>'finished'])->get('learn_battle_rooms')->result_array(),'id');if($ids)$this->db->where('user_id',$uid)->where_in('room_id',$ids)->delete('learn_battle_participants');}else return false;$this->db->trans_complete();return $this->db->trans_status();}}
